34	using namespace nvcv::legacy::helpers;
35	
36	// Flip is a pure pixel remap, so it is memory/latency-bound: one element per thread leaves too few
37	// memory requests in flight (ncu on the single-channel uchar kernel: DRAM 45%, "latency issues").
38	// Each thread instead processes NIX columns strided by the total x-thread count, so NIX independent
39	// loads/stores are issued together (memory-level parallelism) while consecutive threads still touch
40	// consecutive columns (coalesced). NIX>1 needs the grid sized to divUp(width, NIX) x-threads. The
41	// remap is unchanged, so every output is bit-exact with the one-element-per-thread version.
42	constexpr int kFlipNIX       = 4;
43	constexpr int kFlipScalarNIX = 1;
44	
45	inline bool CurrentDeviceIsSM86()
46	{
47	    int dev = 0;
48	    if (cudaGetDevice(&dev) != cudaSuccess)
49	        return false;
50	
51	    cudaDeviceProp prop{};
52	    if (cudaGetDeviceProperties(&prop, dev) != cudaSuccess)
53	        return false;
54	
55	    return prop.major == 8 && prop.minor == 6;
56	}
57	
58	template<int NIX, typename SrcWrapper, typename DstWrapper>
59	__global__ void flipHorizontal(SrcWrapper src, DstWrapper dst, Size2D dstSize)
60	{
61	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
62	    const int32_t batch_idx = get_batch_idx();
63	    if (dst_y >= dstSize.h)
64	        return;
65	
66	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
67	    const int32_t stride = gridDim.x * blockDim.x;
68	    const int32_t width  = dstSize.w;
69	
70	#pragma unroll
71	    for (int i = 0; i < NIX; ++i)
72	    {
73	        const int32_t dst_x = x0 + i * stride;
74	        if (dst_x < width)
75	        {
76	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, dst_y, (width - 1 - dst_x));
77	        }
78	    }
79	}
80	
81	template<int NIX, typename SrcWrapper, typename DstWrapper>
82	__global__ void flipVertical(SrcWrapper src, DstWrapper dst, Size2D dstSize)
83	{
84	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
85	    const int32_t batch_idx = get_batch_idx();
86	    if (dst_y >= dstSize.h)
87	        return;
88	
89	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
90	    const int32_t stride = gridDim.x * blockDim.x;
91	    const int32_t width  = dstSize.w;
92	    const int32_t src_y  = dstSize.h - 1 - dst_y;
93	
94	#pragma unroll
95	    for (int i = 0; i < NIX; ++i)
96	    {
97	        const int32_t dst_x = x0 + i * stride;
98	        if (dst_x < width)
99	        {
100	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, src_y, dst_x);
101	        }
102	    }
103	}
104	
105	template<int NIX, typename SrcWrapper, typename DstWrapper>
106	__global__ void flipHorizontalVertical(SrcWrapper src, DstWrapper dst, Size2D dstSize)
107	{
108	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
109	    const int32_t batch_idx = get_batch_idx();
110	    if (dst_y >= dstSize.h)
111	        return;
112	
113	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
114	    const int32_t stride = gridDim.x * blockDim.x;
115	    const int32_t width  = dstSize.w;
116	    const int32_t src_y  = dstSize.h - 1 - dst_y;
117	
118	#pragma unroll
119	    for (int i = 0; i < NIX; ++i)
120	    {
121	        const int32_t dst_x = x0 + i * stride;
122	        if (dst_x < width)
123	        {
124	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, src_y, (width - 1 - dst_x));
125	        }
126	    }
127	}
128	
129	template<int NIX, typename SrcWrap, typename DstWrap>
130	void runFlipKernel(SrcWrap src, DstWrap dst, Size2D dstSize, int numSamples, int32_t flipCode, cudaStream_t stream)
131	{
132	    dim3 blockSize(32, 8, 1);
133	    dim3 gridSize(divUp(divUp(dstSize.w, NIX), static_cast<int>(blockSize.x)), divUp(dstSize.h, blockSize.y),
134	                  numSamples);
135	
136	    if (flipCode > 0)
137	    {
138	        flipHorizontal<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
139	        checkKernelErrors();
140	    }
141	    else if (flipCode == 0)
142	    {
143	        flipVertical<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
144	        checkKernelErrors();
145	    }
146	    else
147	    {
148	        flipHorizontalVertical<NIX><<<gridSize, blockSize, 0, stream>>>(src, dst, dstSize);
149	        checkKernelErrors();
150	    }
151	}
152	
153	template<typename T, int NIX>
154	ErrorCode flipImpl(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output, const int32_t flipCode,
155	                   cudaStream_t stream)
156	{
157	    auto outAccess = TensorDataAccessStridedImagePlanar::Create(output);
158	    NVCV_ASSERT(outAccess);
159	
160	    auto inAccess = TensorDataAccessStridedImagePlanar::Create(input);
161	    NVCV_ASSERT(inAccess);
162	
163	    Size2D dstSize{outAccess->numCols(), outAccess->numRows()};
164	
165	    int64_t inMaxStride  = inAccess->sampleStride() * inAccess->numSamples();
166	    int64_t outMaxStride = outAccess->sampleStride() * outAccess->numSamples();
167	    if (std::max(inMaxStride, outMaxStride) <= cuda::TypeTraits<int32_t>::max)
168	    {
169	        auto src = cuda::CreateTensorWrapNHW<const T, int32_t>(input);
170	        auto dst = cuda::CreateTensorWrapNHW<T, int32_t>(output);
171	
172	        runFlipKernel<NIX>(src, dst, dstSize, outAccess->numSamples(), flipCode, stream);
173	    }
174	    else
175	    {
176	        LOG_ERROR("Input or output size exceeds " << cuda::TypeTraits<int32_t>::max << ". Tensor is too large.");
177	        return ErrorCode::INVALID_PARAMETER;
178	    }
179	
180	#ifdef CUDA_DEBUG_LOG
181	    checkCudaErrors(cudaStreamSynchronize(stream));
182	    checkCudaErrors(cudaGetLastError());
183	#endif // CUDA_DEBUG_LOG
184	
185	    return ErrorCode::SUCCESS;
186	}
187	
188	template<typename T>
189	ErrorCode flip(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output, const int32_t flipCode,
190	               cudaStream_t stream)
191	{
192	    return flipImpl<T, kFlipNIX>(input, output, flipCode, stream);
193	}
194	
195	template<typename T>
196	ErrorCode flipScalar(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output, const int32_t flipCode,
197	                     cudaStream_t stream)
198	{
199	    return flipImpl<T, kFlipScalarNIX>(input, output, flipCode, stream);
200	}
201	
202	// Wide single-channel flip: a run of VEC contiguous columns is loaded/stored as one MakeType<T,VEC>
203	// vector. A single-channel uchar plane moves only 1 byte/thread, so even with NIX MLP the kernel pays
204	// the per-element index/branch overhead VEC times more than it must; coalescing VEC columns into one
205	// wide access cuts that overhead ~VEC x and raises bytes/thread. Vertical flip keeps the column order,
206	// so the source vector is the same column block in row (H-1-y) -- a direct wide copy. Horizontal flip
207	// reverses the columns, so a destination block [j*VEC .. j*VEC+VEC-1] maps to the mirrored source block
208	// (W/VEC-1-j) with its VEC lanes reversed in registers; this is exact only when the column count is a
209	// multiple of VEC (caller-checked) so the block boundaries line up. The result is bit-identical to the
210	// scalar single-channel flip.
211	template<int VEC, typename WideT>
212	__device__ __forceinline__ WideT flipLanes(WideT v)
213	{
214	    WideT out;
215	#pragma unroll
216	    for (int k = 0; k < VEC; ++k)
217	    {
218	        cuda::GetElement(out, k) = cuda::GetElement(v, VEC - 1 - k);
219	    }
220	    return out;
221	}
222	
223	template<int NIX, int VEC, typename SrcWrapper, typename DstWrapper>
224	__global__ void flipWideHorizontal(SrcWrapper src, DstWrapper dst, Size2D vecSize)
225	{
226	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
227	    const int32_t batch_idx = get_batch_idx();
228	    if (dst_y >= vecSize.h)
229	        return;
230	
231	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
232	    const int32_t stride = gridDim.x * blockDim.x;
233	    const int32_t wvec   = vecSize.w;
234	
235	#pragma unroll
236	    for (int i = 0; i < NIX; ++i)
237	    {
238	        const int32_t dst_x = x0 + i * stride;
239	        if (dst_x < wvec)
240	        {
241	            *dst.ptr(batch_idx, dst_y, dst_x) = flipLanes<VEC>(*src.ptr(batch_idx, dst_y, (wvec - 1 - dst_x)));
242	        }
243	    }
244	}
245	
246	template<int NIX, int VEC, typename SrcWrapper, typename DstWrapper>
247	__global__ void flipWideVertical(SrcWrapper src, DstWrapper dst, Size2D vecSize)
248	{
249	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
250	    const int32_t batch_idx = get_batch_idx();
251	    if (dst_y >= vecSize.h)
252	        return;
253	
254	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
255	    const int32_t stride = gridDim.x * blockDim.x;
256	    const int32_t wvec   = vecSize.w;
257	    const int32_t src_y  = vecSize.h - 1 - dst_y;
258	
259	#pragma unroll
260	    for (int i = 0; i < NIX; ++i)
261	    {
262	        const int32_t dst_x = x0 + i * stride;
263	        if (dst_x < wvec)
264	        {
265	            *dst.ptr(batch_idx, dst_y, dst_x) = *src.ptr(batch_idx, src_y, dst_x);
266	        }
267	    }
268	}
269	
270	template<int NIX, int VEC, typename SrcWrapper, typename DstWrapper>
271	__global__ void flipWideHorizontalVertical(SrcWrapper src, DstWrapper dst, Size2D vecSize)
272	{
273	    const int32_t dst_y     = blockIdx.y * blockDim.y + threadIdx.y;
274	    const int32_t batch_idx = get_batch_idx();
275	    if (dst_y >= vecSize.h)
276	        return;
277	
278	    const int32_t x0     = blockIdx.x * blockDim.x + threadIdx.x;
279	    const int32_t stride = gridDim.x * blockDim.x;
280	    const int32_t wvec   = vecSize.w;
281	    const int32_t src_y  = vecSize.h - 1 - dst_y;
282	
283	#pragma unroll
284	    for (int i = 0; i < NIX; ++i)
285	    {
286	        const int32_t dst_x = x0 + i * stride;
287	        if (dst_x < wvec)
288	        {
289	            *dst.ptr(batch_idx, dst_y, dst_x) = flipLanes<VEC>(*src.ptr(batch_idx, src_y, (wvec - 1 - dst_x)));
290	        }
291	    }
292	}
293	
294	// True when the single-channel flip can use VEC-wide contiguous vectorization: cols divisible by VEC,
295	// and both base pointers + row/sample strides aligned to the VEC-wide vector type.
296	template<typename T, int VEC>
297	static bool wideSingleChannelEligible(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output)
298	{
299	    auto in  = TensorDataAccessStridedImagePlanar::Create(input);
300	    auto out = TensorDataAccessStridedImagePlanar::Create(output);
301	    if (!in || !out)
302	        return false;
303	    if (in->numCols() % VEC != 0)
304	        return false;
305	    const std::uintptr_t a  = alignof(cuda::MakeType<T, VEC>);
306	    auto                 ok = [a](std::uintptr_t base, int64_t rowS, int64_t smpS)
307	    {
308	        return ((base | static_cast<std::uintptr_t>(rowS) | static_cast<std::uintptr_t>(smpS)) & (a - 1)) == 0;
309	    };
310	    return ok(reinterpret_cast<std::uintptr_t>(input.basePtr()), in->rowStride(), in->sampleStride())
311	        && ok(reinterpret_cast<std::uintptr_t>(output.basePtr()), out->rowStride(), out->sampleStride());
312	}
313	
314	template<typename T, int VEC>
315	ErrorCode flipWideSingleChannel(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output,
316	                                const int32_t flipCode, cudaStream_t stream)
317	{
318	    using WideT = cuda::MakeType<T, VEC>;
319	
320	    auto inAccess  = TensorDataAccessStridedImagePlanar::Create(input);
321	    auto outAccess = TensorDataAccessStridedImagePlanar::Create(output);
322	    NVCV_ASSERT(inAccess);
323	    NVCV_ASSERT(outAccess);
324	
325	    // Each "pixel" spans VEC contiguous columns; numCols is divisible by VEC (caller-checked).
326	    Size2D  vecSize{outAccess->numCols() / VEC, outAccess->numRows()};
327	    int64_t inMaxStride  = inAccess->sampleStride() * inAccess->numSamples();
328	    int64_t outMaxStride = outAccess->sampleStride() * outAccess->numSamples();
329	    if (std::max(inMaxStride, outMaxStride) > cuda::TypeTraits<int32_t>::max)
330	    {
331	        LOG_ERROR("Input or output size exceeds " << cuda::TypeTraits<int32_t>::max << ". Tensor is too large.");
332	        return ErrorCode::INVALID_PARAMETER;
333	    }
334	
335	    auto src = cuda::CreateTensorWrapNHW<const WideT, int32_t>(input);
336	    auto dst = cuda::CreateTensorWrapNHW<WideT, int32_t>(output);
337	
338	    dim3 blockSize(32, 8, 1);
339	    dim3 gridSize(divUp(divUp(vecSize.w, kFlipNIX), static_cast<int>(blockSize.x)), divUp(vecSize.h, blockSize.y),
340	                  outAccess->numSamples());
341	
342	    if (flipCode > 0)
343	    {
344	        flipWideHorizontal<kFlipNIX, VEC><<<gridSize, blockSize, 0, stream>>>(src, dst, vecSize);
345	    }
346	    else if (flipCode == 0)
347	    {
348	        flipWideVertical<kFlipNIX, VEC><<<gridSize, blockSize, 0, stream>>>(src, dst, vecSize);
349	    }
350	    else
351	    {
352	        flipWideHorizontalVertical<kFlipNIX, VEC><<<gridSize, blockSize, 0, stream>>>(src, dst, vecSize);
353	    }
354	    checkKernelErrors();
355	    return ErrorCode::SUCCESS;
356	}
357	
358	// Single-channel flip: use VEC-wide contiguous vectorization when the columns are VEC-divisible and the
359	// buffers are vector-aligned, otherwise fall back to the scalar single-channel kernel. Used by the
360	// interleaved C==1 path and by the planar path (each NCHW plane is a single-channel image).
361	template<typename T>
362	ErrorCode flipSingleChannel(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output,
363	                            const int32_t flipCode, cudaStream_t stream)
364	{
365	    if (wideSingleChannelEligible<T, 4>(input, output))
366	        return flipWideSingleChannel<T, 4>(input, output, flipCode, stream);
367	    return flip<T>(input, output, flipCode, stream);
368	}
369	
370	ErrorCode Flip::infer(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output, const int32_t flipCode,
371	                      cudaStream_t stream)
372	{
373	    if (input.dtype() != output.dtype())
374	    {
375	        LOG_ERROR("Invalid DataType between input (" << input.dtype() << ") and output (" << output.dtype() << ")");
376	        return ErrorCode::INVALID_DATA_TYPE;
377	    }
378	
379	    DataFormat inputFormat  = GetLegacyDataFormat(input.layout());
380	    DataFormat outputFormat = GetLegacyDataFormat(output.layout());
381	    if (inputFormat != outputFormat)
382	    {
383	        LOG_ERROR("Invalid DataFormat between input (" << inputFormat << ") and output (" << outputFormat << ")");
384	        return ErrorCode::INVALID_DATA_FORMAT;
385	    }
386	
387	    DataFormat format = inputFormat;
388	    if (!(format == kNHWC || format == kHWC || format == kNCHW || format == kCHW))
389	    {
390	        LOG_ERROR("Invalid input DataFormat " << format
391	                                              << ", the valid DataFormats are: \"NHWC\", \"HWC\", \"NCHW\", \"CHW\"");
392	        return ErrorCode::INVALID_DATA_FORMAT;
393	    }
394	
395	    const bool isPlanar = (format == kNCHW || format == kCHW);
396	
397	    cuda_op::DataType dataType = GetLegacyDataType(input.dtype());
398	    if (!(dataType == kCV_8U || dataType == kCV_16U || dataType == kCV_32S || dataType == kCV_32F))
399	    {
400	        LOG_ERROR("Invalid DataType " << dataType);
401	        return ErrorCode::INVALID_DATA_TYPE;
402	    }
403	
404	    auto inputWrapper = TensorDataAccessStridedImagePlanar::Create(input);
405	    NVCV_ASSERT(inputWrapper);
406	
407	    cuda_op::DataShape inputShape = GetLegacyDataShape(inputWrapper->infoShape());
408	    // Planar 2-channel layout is rejected (no defined 2-plane format); the interleaved path likewise
409	    // does not support 2 channels (matches the Normalize and Resize operators).
410	    if (inputShape.C > 4 || inputShape.C == 2)
411	    {
412	        LOG_ERROR("Invalid channel number " << inputShape.C);
413	        return ErrorCode::INVALID_DATA_SHAPE;
414	    }
415	
416	    // using flip_t = void(const TensorDataStridedCuda & input,
417	    //                     const TensorDataStridedCuda & output,
418	    //                     const int32_t flipCode, cudaStream_t stream);
419	    typedef ErrorCode (*flip_t)(const TensorDataStridedCuda &input, const TensorDataStridedCuda &output,
420	                                const int32_t flipCode, cudaStream_t stream);
421	
422	    // Column 0 (single channel) routes through flipSingleChannel, which picks the wide-vectorized
423	    // kernel when eligible and otherwise the scalar single-channel kernel. The planar path also uses
424	    // column 0 (each NCHW plane is a single-channel image).
425	    static const flip_t funcs[6][4] = {
426	        {  flipSingleChannel<uchar>, 0,       flip<uchar3>,  flip<uchar4>},
427	        {                         0, 0,                  0,             0},
428	        { flipSingleChannel<ushort>, 0,      flip<ushort3>, flip<ushort4>},
429	        {                         0, 0,                  0,             0},
430	        {flipSingleChannel<int32_t>, 0,         flip<int3>,    flip<int4>},
431	        {  flipSingleChannel<float>, 0, flipScalar<float3>,  flip<float4>}
432	    };
433	
434	    const int32_t channels = inputShape.C;
435	
436	    if (isPlanar)
437	    {
438	        // View each of the N*C channel planes as a single-channel sample and reuse the interleaved
439	        // single-channel flip kernel (funcs column 0). Channels are independent in flip, so this is
440	        // bit-exact with flipping the equivalent NHWC single-channel data. The flattened plane count
441	        // becomes the kernel's grid.z, capped at CUDA's 65535 limit; compute it in 64-bit to avoid
442	        // overflow. The flattened view is only valid when the planes are tightly packed across samples.
443	        auto outputWrapper = TensorDataAccessStridedImagePlanar::Create(output);
444	        NVCV_ASSERT(outputWrapper);
445	
446	        const int64_t numSamples = inputWrapper->numSamples();
447	        if (numSamples > 1
448	            && (inputWrapper->sampleStride() != static_cast<int64_t>(channels) * inputWrapper->chStride()
449	                || outputWrapper->sampleStride() != static_cast<int64_t>(channels) * outputWrapper->chStride()))
450	        {
451	            LOG_ERROR("Planar flip of a batched tensor requires tightly packed channel planes");
452	            return ErrorCode::INVALID_DATA_SHAPE;
453	        }
454	        if (numSamples * channels > 65535)
455	        {
456	            LOG_ERROR("Planar flip requires numSamples * numChannels <= 65535 (CUDA grid-z limit)");
457	            return ErrorCode::INVALID_DATA_SHAPE;
458	        }
459	
460	        auto srcView = cvcuda::priv::PlanarAsSingleChannelView(input, *inputWrapper);
461	        auto dstView = cvcuda::priv::PlanarAsSingleChannelView(output, *outputWrapper);
462	        // GA102/SM86 regresses on vectorized planar tensor float3; keep other SKUs on the wider path.
463	        if (dataType == kCV_32F && channels == 3 && CurrentDeviceIsSM86())
464	        {
465	            return flipScalar<float>(srcView, dstView, flipCode, stream);
466	        }
467	        return funcs[dataType][0](srcView, dstView, flipCode, stream);
468	    }
469	
470	    return funcs[dataType][channels - 1](input, output, flipCode, stream);
471	}
472	
473	} // namespace nvcv::legacy::cuda_op
