    HandleType handle()
    {
        return reinterpret_cast<HandleType>(this);
    }

    Version version() const
    {
        return CURRENT_VERSION;
    }
};

IOperator *ToOperatorPtr(NVCVOperatorHandle handle);

template<class T, class... Args>
inline NVCVOperatorHandle CreateOperatorHandle(Args &&...args)
{
    auto op = std::make_unique<T>(std::forward<Args>(args)...);
    return reinterpret_cast<NVCVOperatorHandle>(op.release());
}

inline void DestroyOperatorHandle(NVCVOperatorHandle handle)
{
    std::unique_ptr<IOperator> op(ToOperatorPtr(handle));
    (void)op;
}

template<class T>
inline T *ToDynamicPtr(NVCVOperatorHandle h)
{
    return dynamic_cast<T *>(ToOperatorPtr(h));
}

template<class T>
inline T &ToDynamicRef(NVCVOperatorHandle h)
{
    if (h == nullptr)
    {
        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT, "Handle cannot be NULL");
    }

    if (T *child = ToDynamicPtr<T>(h))
    {
        return *child;
    }
    else
    {
        throw nvcv::Exception(nvcv::Status::ERROR_NOT_COMPATIBLE,
                              "Handle doesn't correspond to the requested object or was already destroyed.");
    }
}

